      const steps=items=>`<div class="grammar-steps">${items.map((x,i)=>`<div><b>${i+1}</b><span>${esc(x)}</span></div>`).join('')}</div>`;
      const title=slide.visualTitle||slide.title;
      if(v==='grammar-table')return board(title,table(data),course.source?.split('—')[0]||'SOURCE');
      if(v==='grammar-steps')return board(title,steps(data),'METHOD');
      if(v==='grammar-formula')return board(title,`<div class="grammar-formula"><strong>${esc(data[0]?.s||slide.rule||'')}</strong><span>${esc(data.slice(1).map(x=>x.s).join(' · ')||slide.example||'')}</span></div>`,'FORMULA');
      if(v==='grammar-compare')return board(title,`<div class="grammar-split"><div class="grammar-side a"><b>${esc(data[0]?.b||'FORM A')}</b><strong>${esc(data[0]?.s||'')}</strong><span>${esc(data[0]?.t||'')}</span></div><div class="grammar-arrow">⇄</div><div class="grammar-side b"><b>${esc(data[1]?.b||'FORM B')}</b><strong>${esc(data[1]?.s||'')}</strong><span>${esc(data[1]?.t||'')}</span></div></div>`,'COMPARE');
      if(v==='grammar-trap')return board(title,grid(data),'TRAP SCAN');
      if(v==='grammar-score')return board(title,`<div class="grammar-score">${data.map(d=>`<div><b>${esc(d.b||'')}</b><span>${esc(d.s||'')}</span></div>`).join('')}</div>`,'SCORE');
      if(v==='grammar-map')return board(title,`<div class="grammar-master"><div class="grammar-root">${esc(data[0]?.s||'MASTER MAP')}</div><div class="grammar-grid">${data.slice(1).map(card).join('')}</div></div>`,'MASTER MAP');
      if(v==='grammar-cards'||v==='grammar-radar'||v==='grammar-ladder')return board(title,grid(data),v.replace('grammar-','').toUpperCase());
      return board(title,flow(data.length?data:[{b:'SIGNAL',s:'find the cue',t:'blue'},{b:'RULE',s:'choose the form',t:'green'},{b:'TRAP',s:'verify context',t:'gold'}]),'ADMISSION');
