      if(v==='pos-conj-families')return board('THREE CONJUNCTION FAMILIES',`<div class="course-pos-branch"><div class="course-pos-root">CONJUNCTION = JOINER</div><div class="course-pos-branches">${card('COORDINATING','FANBOYS','blue')}${card('SUBORDINATING','because · if','green')}${card('CORRELATIVE','either…or','purple')}${card('RELATIVE NOTE','who/that member','gold')}</div></div>`,'CONJUNCTION');
      if(v==='pos-fanboys')return board('FANBOYS RAIL',`<div class="course-pos-chipline"><span>F · for</span><span>A · and</span><span>N · nor</span><span>B · but</span><span>O · or</span><span>Y · yet</span><span>S · so</span></div><div class="course-pos-ruleline"><div><b>EQUAL</b><span>two equal units</span></div><div><b>JOIN</b><span>coordinating</span></div><div><b>TRAP</b><span>because is subordinate</span></div></div>`,'CONJUNCTION');
