  const refreshCourse=()=>{const y=window.scrollY||0,renderNow=window.render;renderNow?.();requestAnimationFrame?.(()=>window.scrollTo(0,y))};
  window.courseAnswerV3=(cid,qid,choice)=>{const c=courseById(cid),q=courseQuestions(c).find(x=>x.id===qid),e=exam();if(!q||e.answers[qid])return;e.answers[qid]={choice,correct:choice===Number(q.a)};const p=courseProgress(cid),stats={...(p.stats||{})},old=stats[qid]||{attempts:0,correct:0,wrong:0};stats[qid]={attempts:old.attempts+1,correct:old.correct+(choice===Number(q.a)?1:0),wrong:old.wrong+(choice===Number(q.a)?0:1)};saveCourseProgress(cid,{stats});refreshCourse()};
