  if(!window.__courseKeyboardV3){window.__courseKeyboardV3=true;document.addEventListener('keydown',ev=>{if(!path().includes('/exam')||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||!['1','2','3','4'].includes(ev.key))return;const option=document.querySelector('.course-bank-option:not(:disabled):nth-child('+ev.key+')');if(option){ev.preventDefault();option.click()}})}
